targets.query:
from(bucket: "model_comparison")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "metric_results")
  |> filter(fn: (r) => r.model_type == "predicted")
  |> filter(fn: (r) => r._field == "${metric_choice}")
  // $param_value = All -> вся история прогнозов по выбранному параметру;
  // конкретное значение (в т.ч. проброшенное фронтом через var-param_value)
  // оставляет только точки с этим значением тега cfg_<param>.
  |> filter(fn: (r) => r["cfg_${param_name}"] =~ /^${param_value}$/)
  |> keep(columns: ["_time", "_field", "_value", "model_type", "support_level"])
  |> group(columns: ["model_type"])
  |> yield(name: "mean")
